{
    struct atm_vcc *vcc;
    int len, val;

    if (optlen == NULL || get_user(len, optlen))
        return -EFAULT;

    if (optname < 0)
        return -EINVAL;

    vcc = ATM_SD(sock);
    if (!vcc)
        return -ENOTCONN;

    switch (optname) {
    case SO_ATMQOS:
        if (len < sizeof(struct atm_qos)) {
            len = sizeof(struct atm_qos);
            if (put_user(len, optlen))
                return -EFAULT;
        }
        if (copy_to_user(optval, &vcc->qos, sizeof(struct atm_qos)))
            return -EFAULT;
        break;
