int atm_getsockopt(struct socket *sock, int level, int optname,
                   char __user *optval, int __user *optlen)
{
    struct atm_vcc *vcc;
    int len;

    if (get_user(len, optlen))
        return -EFAULT;
    if (len < 0)
        return -EINVAL;

    vcc = ATM_SOCK(sock)->vcc;
    if (!vcc)
        return -ENOTCONN;

    if (level == SOL_ATM) {
        switch (optname) {
        case ATM_SKB_SIZE:
        case ATM_HDR_SIZE:
        case ATM_MTU:
        case ATM_MAX_AAL:
        case ATM_PROTOCOL:
        case ATM_DEFAULT_VC:
        case ATM_REUSEADDR:
        case ATM_REUSEPORT:
        case ATM_NODELAY:
        case ATM_BROADCAST:
        case ATM_DEBUG:
        case ATM_VCC:
            if (!access_ok(VERIFY_WRITE, optval, len))
                return -EFAULT;
            if (len < sizeof(int))
                return -EINVAL;
            if (copy_to_user(optval, &vcc->qos, len))
                return -EFAULT;
            break;
        default:
            if (vcc->dev && vcc->dev->ops->getsockopt)
                return vcc->dev->ops->getsockopt(vcc, level, optname, optval, optlen);
            else
                return -ENOPROTOOPT;
        }
        return 0;
    }

    if (vcc->dev && vcc->dev->ops->getsockopt)
        return vcc->dev->ops->getsockopt(vcc, level, optname, optval, optlen);
    return -ENOPROTOOPT;
}

#include <linux/socket.h>
#include <linux/un.h>
#include <linux/uaccess.h>
#include <linux/atm.h>
#include <net/sock.h>

int atm_getsockopt(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen)
{
	int err = 0;
	struct atm_vcc *vcc = ATM_SOCKET(sock)->vcc;
	void *data;

	if (vcc == NULL)
		return -ENOTCONN;

	switch (optname) {
	case SO_ATMQOS:
		{
			struct atm_qos qos;
			if (copy_from_user(&qos, vcc->qos, sizeof(qos)))
				return -EFAULT;
			if (copy_to_user(optval, &qos, sizeof(qos)))
				return -EFAULT;
			if (put_user(sizeof(qos), optlen))
				return -EFAULT;
			break;
		}
	default:
		if (vcc->dev && vcc->dev->ops->getsockopt)
			err = vcc->dev->ops->getsockopt(vcc, level, optname, optval, optlen);
		else
			err = -ENOPROTOOPT;
		break;
	}

	return err;
}

